-- 칸토 초크를 사이드 컨트롤 버전으로 다시 씀 (D-92). 본인 의견("주로 사이드 컨트롤에서 많이 쓰는 초크") → 다시 조사:
-- Jiu Jitsu Legacy(내 쪽 깃 · 먼 팔을 잡아 기울이기 · 가까운 다리를 머리 위로) · BJJ World(같은 쪽 깃을 목 가까이 깊게 · 다리 넘겨 무릎 내리기)
-- · LowKick MMA(깃 그립 · 먼 팔 언더훅으로 들어 올려 공간 · 머리 넘어 다리를 뒤통수에 걸고 깃 당기기) · VR Jiu-Jitsu(엄지 안쪽 그립을 머리 뒤에).
-- 좌우는 우리 사이드 기준(상대 오른쪽에서 · 내 왼팔이 머리 쪽)과 '암바 (사이드)' 카드(내 왼다리를 머리 위로)에 맞춤.
-- 같은 카드(slug)를 고쳐 이미 연결된 기록 · 숙련도는 그대로 둔다. 가드 버전 이름은 다른 이름으로 남긴다.
update public.techniques set
  position_id = (select id from public.positions where slug = 'side-control'),
  name_ko = '칸토 초크 (사이드)', name_en = 'Canto Choke', aliases = array['칸토초크','칸토 초크','칸토 초크 (가드)','플라비오 칸토 초크','Canto Choke']::text[],
  steps = array['상대 오른쪽에서 사이드: 내 왼손을 상대 머리 뒤로 넣어 상대 오른쪽 깃(내 쪽 깃)을 목 가까이 깊게 잡는다(엄지가 깃 안쪽)','내 오른손으로 상대 왼팔(먼 팔)을 잡거나 언더훅해 상대를 내 쪽으로 당겨 옆으로 세운다 — 상대 뒤통수가 드러나게','깃을 놓지 않은 채 일어나며 암바 때처럼 내 왼다리를 상대 머리 위로 넘긴다','내 왼쪽 오금을 상대 뒤통수에 걸고 왼 무릎을 매트 쪽으로 내리며 왼손으로 깃을 당긴다','천천히 조인다 · 탭하면 바로 푼다']::text[],
  source = '운영자 승인(대기 목록, D-89 · D-92) · AI 초안(우리 말로 작성) · 참고: Jiu Jitsu Legacy · BJJ World · LowKick MMA · VR Jiu-Jitsu',
  sort_order = coalesce((select max(t.sort_order) from public.techniques t join public.positions p on p.id = t.position_id where p.slug = 'side-control'), 0) + 1,
  kind = 'submission', role = 'top', ends_at = '{}'::text[],
  key_points = array['모든 게 깃 그립에서 시작한다 — 내 쪽 깃을 목 가까이 깊게, 겉보기엔 평범한 그립이라 상대가 늦게 알아챈다','다리를 넘기기 전에 상대를 내 쪽으로 돌려 세운다 — 뒤통수가 보여야 오금이 걸린다','다리 넘기는 동작은 사이드 암바와 같다 — 넘기는 동안 깃과 무게로 상대를 계속 누른다','도복 깃을 쓰는 기술이라 노기에서는 쓸 수 없다']::text[], mistakes = array['상대가 등을 바닥에 붙인 채 다리부터 넘기면 다리가 얼굴에 걸려 조이지 않는다 → 먼 팔을 당겨 옆으로 세운 뒤 넘긴다','깃을 얕게 잡으면 다리를 내려도 목이 조이지 않는다 → 목 가까이 깊게 잡는다','다리를 넘기다 누르기를 놓치면 상대가 돌아 빠진다 → 깃을 잡은 왼손과 가슴 무게를 끝까지 유지한다']::text[], if_blocked = array['상대가 내 쪽 팔을 뻗어 막으면 → 암바 (사이드)','상대가 등을 바닥에 붙이고 버티면 → 브레드커터 초크','상대가 엎드려 터틀로 돌면 → 터틀에서 백 테이크']::text[], defense = array['상대가 내 오른쪽에서 사이드를 잡고 상대 왼손이 내 머리 뒤로 들어와 내 오른쪽 깃을 깊게 잡으면 칸토 초크 신호','깃 그립부터 두 손으로 떼고, 상대 쪽으로 돌아눕지 말고 등을 바닥에 붙여 뒤통수를 내주지 않는다','상대 왼다리가 머리 위로 넘어오면 턱을 당기고 손으로 다리를 막아 뒤통수에 걸리지 않게 한다','다리가 걸려 목이 조여 오면 버티지 말고 탭한다']::text[]
where slug = 'canto-choke' and owner_id is null and name_ko = '칸토 초크 (가드)';
